INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('ecbyna96n5pji3ybzwrecbyns9a9myrl', '2026-Q2', 'Jun–Jul/2026 (T2)', '2026-07-21T10:57'::timestamptz, 'Matheus Coelho Lopes', 'matheus coelho lopes', 'PHARUS', 'Nelson Marques', 7.0, 'Neutro', 8.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Entendi o método, mas ainda não implementei o suficiente', 'Sou bem atendido pelas pessoas, todo mundo muito gente boa, mas já se passaram praticamente 6 meses desde o inicio do meu projeto e até agora não fiz nada do que foi montado pros meus planos, não conseguiram fazer a autoconstrução, nao apareceu nenhuma carta de consórcio que seja atraente, acabei de perder a oportunidade dos leiloes porque em menos de 24 horas todas as vagas foram preenchidas, a unica coisa que consegui fazer nesses 6 meses foi investir no arcadia, mas que nao estava originalmente nos meu plano patrimonial montado pelo acessor.', 'Eu gostaria de seguir meu plano como foi me passado', NULL, 'Eu gostei muito da empresa e das pessoas, só queria ter um pouco mais de clareza sobre as coisas, gosto de entender os detalhes até mesmo para aprender', 'Nao', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'ecbyna96n5pji3ybzwrecbyns9a9myrl', 'cadastro 2026-T2 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = E